BORRADOS = {'etcd-server/config/etcd-server.etcd-vm.json': '3ffa06ad626428568168bb1df8f02b7fbd939c6e5a4e9407fc69f93e9f2b9020', 'etcd-server/config/ml-defender-etcd-server.service': 'e1d9a521ff88d360b55e0aa5d15bd53b220e758ac1ff075265d6bfddde0e86b8'}      # ruta: sha256 previo

def sha(b):
    return hashlib.sha256(b).hexdigest()

def main():
    if len(sys.argv) != 3 or sys.argv[1] not in ('--check', '--apply'):
        sys.exit('uso: %s --check|--apply <raiz_repo>' % sys.argv[0])
    modo, raiz = sys.argv[1], sys.argv[2]
    p = lambda r: os.path.join(raiz, r)
    lee = lambda r: open(p(r), 'rb').read()
    ya = (all(os.path.isfile(p(r)) and sha(lee(r)) == fin for r, (_, fin, _) in MODIFICADOS.items())
          and all(os.path.isfile(p(r)) and lee(r) == c.encode() for r, (_, c) in REESCRITOS.items())
          and all(os.path.isfile(p(r)) and lee(r) == c.encode() for r, c in NUEVOS.items())
          and not any(os.path.exists(p(r)) for r in BORRADOS))
    if ya:
        print('YA APLICADO: no se toca nada.'); return 0
    escribir = {}
    for r, (prev, fin, cs) in MODIFICADOS.items():
        if not os.path.isfile(p(r)):
            print('FALLA: no existe %s; no se toca nada.' % r); return 1
        b = lee(r)
        if sha(b) != prev:
            print('FALLA: %s no está en el estado esperado (sha256 %s); no se toca nada.' % (r, sha(b)[:16])); return 1
        t = b.decode('utf-8')
        for i, (v, n, k) in enumerate(cs, 1):
            if t.count(v) != k:
                print('FALLA: %s cambio %d: %d apariciones (se exigen %d); no se toca nada.' % (r, i, t.count(v), k)); return 1
            t = t.replace(v, n)
        if sha(t.encode('utf-8')) != fin:
            print('FALLA: %s no da el sha256 final; no se toca nada.' % r); return 1
        escribir[r] = t.encode('utf-8')
    for r, (prev, c) in REESCRITOS.items():
        if not os.path.isfile(p(r)) or sha(lee(r)) != prev:
            print('FALLA: %s no está en el estado esperado; no se toca nada.' % r); return 1
        escribir[r] = c.encode('utf-8')
    for r in NUEVOS:
        if os.path.exists(p(r)):
            print('FALLA: %s ya existe; no se toca nada.' % r); return 1
    for r, prev in BORRADOS.items():
        if not os.path.isfile(p(r)) or sha(lee(r)) != prev:
            print('FALLA: %s (a borrar) no está en el estado esperado; no se toca nada.' % r); return 1
    if modo == '--check':
        print('APLICABLE: %d modificados, %d reescritos, %d nuevos, %d borrados.' % (len(MODIFICADOS), len(REESCRITOS), len(NUEVOS), len(BORRADOS))); return 0
    for r, b in escribir.items():
        tmp = p(r) + '.d317tmp'
        with open(tmp, 'wb') as o: o.write(b)
        os.chmod(tmp, os.stat(p(r)).st_mode & 0o7777); os.replace(tmp, p(r)); print('  escrito  %s' % r)
    for r, c in NUEVOS.items():
        tmp = p(r) + '.d317tmp'
        with open(tmp, 'wb') as o: o.write(c.encode('utf-8'))
        os.chmod(tmp, 0o644); os.replace(tmp, p(r)); print('  creado   %s' % r)
    for r in BORRADOS:
        os.remove(p(r)); print('  borrado  %s' % r)
    mal = [r for r, b in escribir.items() if lee(r) != b] + [r for r in BORRADOS if os.path.exists(p(r))]
    if mal:
        print('FALLA tras escribir: %s' % ', '.join(mal)); return 1
    print('APLICADO: %d modificados, %d reescritos, %d nuevos, %d borrados.' % (len(MODIFICADOS), len(REESCRITOS), len(NUEVOS), len(BORRADOS))); return 0

if __name__ == '__main__':
    sys.exit(main())
